let $injector = widgetContext.$scope.$injector;
let customDialog = $injector.get(widgetContext.servicesMap.get('customDialog'));
let controller, params;

openAssetsFilterDialog();

function openAssetsFilterDialog() {
    customDialog.customDialog(htmlTemplate, AssetEditDialogController).subscribe();
}

function AssetEditDialogController(instance) {
    const vm = instance;
    const aliasController = widgetContext.dashboard.aliasController;

    controller = widgetContext.$scope.ctx.stateController;
    params = controller.getStateParams();

    vm.allLocationsSelected = true;
    vm.allZonesSelected = true;
    vm.allTypesSelected = true;
    vm.allDepartmentsSelected = true;
    vm.allAlertStatusesSelected = true;

    const pageLink = widgetContext.pageLink(1073741824);

    let oldSelectedLocations = [];

    let hierarchyTree = {};

    vm.assetTypes = [
        {
            label: "Loader",
            value: "Loader"
        },
        {
            label: "Box",
            value: "Box",
        },
        {
            label: "Worker",
            value: "Worker"
        }, 
        {
            label: "Tool",
            value: "Tool"
        }
    ];

    vm.departmentOptions = [
        {
            label: "Department 1",
            value: "Department 1"
        },
        {
            label: "Department 2",
            value: "Department 2"
        },
        {
            label: "Department 3",
            value: "Department 3"
        }
    ];

    vm.statusOptions = [
        {
            label: "Active",
            value: "true"
        },
        {
            label: "Inactive",
            value: "false"
        }
    ];

    vm.alertStatusOptions = [
        {
            label: "Assets with alerts",
            value: "true"
        },
        {
            label: "Assets without alerts",
            value: "false",
        }
    ];

    vm.locationOptions = [];

    vm.zoneOptions = [];

    function atLeastOneTrueValidator() {
        return (formGroup) => {
            const active = formGroup.get('active')?.value;
            const inactive = formGroup.get('inactive')?.value;

            if (active !== true && inactive !== true) {
              return { atLeastOneTrue: true };
            }

            return null;
        };
    }

    vm.filtersFormGroup = vm.fb.group({
        location: [[], [vm.validators.required]],
        zone: [[], [vm.validators.required]],
        type: [vm.assetTypes.map(option => option.value), [vm.validators.required]],
        department: [vm.departmentOptions.map(option => option.value), [vm.validators.required]],
        status: vm.fb.group({
            active: [true, []],
            inactive: [true, []]
        }),
        alertActivity: [vm.alertStatusOptions.map(option => option.value), [vm.validators.required]]
    });

    vm.filtersFormGroup.get("location").valueChanges.subscribe(locations => {
        let currentZoneValue = vm.filtersFormGroup.get("zone").value;

        let updatedZoneIds = [];

        if (locations && locations.length) {
            const newZoneOptions = [];

            locations.forEach(locationId => {
                hierarchyTree[locationId].zones.forEach(zone => {
                    const zoneId = zone.id;
                    newZoneOptions.push({
                        label: zone.zoneName,
                        value: zoneId
                    });

                    updatedZoneIds.push(zoneId);
                });
            });
            vm.zoneOptions = newZoneOptions;
        }

        const newZones = currentZoneValue.filter(zone => updatedZoneIds.includes(zone));

        const selectedLocations = locations.filter(location => !oldSelectedLocations.includes(location));

        if (selectedLocations && selectedLocations.length) {
            hierarchyTree[selectedLocations[0]].zones.forEach(zone => {
                newZones.push(zone.id);
            });
        }

        vm.filtersFormGroup.get("zone").setValue(newZones);

        oldSelectedLocations = locations;
    });

    const locationParams = {
        entityFilter: {
            type: "assetType",
            assetType: "Location"
        },
        pageLink,
        entityFields: [
            {
                type: "ENTITY_FIELD",
                key: "name"
            }
        ]
    };

    let zoneIds = [];
    let zones = {};

    widgetContext.http.post(`/api/entitiesQuery/find`, locationParams)
        .pipe(
            widgetContext.rxjs.switchMap((locationsResponse) => {
                hierarchyTree = {};

                const locationIds = [];
                if(locationsResponse && locationsResponse.data){
                    locationsResponse.data.forEach(locationElement => {
                        const locationId = locationElement.entityId.id;
                        const locationName = locationElement.latest.ENTITY_FIELD.name.value;
                        locationIds.push(locationId);

                        vm.locationOptions.push({
                            label: locationName,
                            value: locationId
                        });

                        hierarchyTree[locationId] = {
                            locationName,
                            locationId,
                            zones: []
                        };
                    });
                }

                widgetContext.detectChanges();

                const zoneQueryParams = {
                    entityFilter: {
                        type: "relationsQuery",
                        multiRoot: true,
                        multiRootEntitiesType: "ASSET",
                        direction: "TO",
                        maxLevel: 1,
                        multiRootEntityIds: locationIds,
                        filters: [{
                            relationType: "ZoneToLocation"
                        }]
                    },
                    pageLink,
                    entityFields: [
                        {
                            type: "ENTITY_FIELD",
                            key: "name"
                        }, {
                            type: "ENTITY_FIELD",
                            key: "parentId"
                        }
                    ]
                };

                return widgetContext.http.post(`/api/entitiesQuery/find`, zoneQueryParams);
            }),
            widgetContext.rxjs.switchMap((zonesResponse) => {
                zoneIds = [];

                if(zonesResponse && zonesResponse.data){
                    zonesResponse.data.forEach((zoneElement) => {
                        const zoneId = zoneElement.entityId.id;
                        const zoneName = zoneElement.latest.ENTITY_FIELD.name.value;
                        const locationId = zoneElement.latest.ENTITY_FIELD.parentId.value;
                        zoneIds.push(zoneId);

                        vm.zoneOptions.push({
                            label: zoneName,
                            value: zoneId
                        });

                        const zone = {
                            zoneName,
                            id: zoneId,
                            assets: [],
                            geofences: [],
                            locationId
                        };

                        zones[zoneId] = zone;
                    });
                }

                const assetQueryParams = {
                    entityFilter: {
                        type: "relationsQuery",
                        multiRoot: true,
                        multiRootEntitiesType: "ASSET",
                        direction: "FROM",
                        maxLevel: 1,
                        multiRootEntityIds: zoneIds,
                        filters: [{
                            relationType: "ZoneToAsset"
                        }]
                    },
                    pageLink,
                    entityFields: [
                        {
                            type: "ENTITY_FIELD",
                            key: "name"
                        },
                        {
                            type: "ENTITY_FIELD",
                            key: "type"
                        },
                        {
                            type: "ENTITY_FIELD",
                            key: "parentId"
                        }
                    ],
                    latestValues: [
                        {
                            type: "ATTRIBUTE",
                            key: "status"
                        },
                        {
                            type: "ATTRIBUTE",
                            key: "alertActivity"
                        }
                    ]
                };

                return  widgetContext.http.post(`/api/entitiesQuery/find`, assetQueryParams);

            }),
            widgetContext.rxjs.switchMap((assetResponse) => {
                if(assetResponse && assetResponse.data){
                    assetResponse.data.forEach(assetElement => {
                        const zoneId = assetElement.latest.ENTITY_FIELD.parentId.value;

                        const asset = {
                            name: assetElement.latest.ENTITY_FIELD.name.value,
                            type: assetElement.latest.ENTITY_FIELD.type.value,
                            status: assetElement.latest.ATTRIBUTE.status.value,
                            alertActivity: assetElement.latest.ATTRIBUTE.alertActivity.value ? assetElement.latest.ATTRIBUTE.alertActivity.value : "false"
                        };

                        zones[zoneId].assets.push(asset);
                    });
                }

                const geofenceQueryParams = {
                    entityFilter: {
                        type: "relationsQuery",
                        multiRoot: true,
                        multiRootEntitiesType: "ASSET",
                        direction: "TO",
                        maxLevel: 1,
                        multiRootEntityIds: zoneIds,
                        filters: [{
                            relationType: "GeofenceToZone"
                        }]
                    },
                    pageLink,
                    entityFields: [
                        {
                            type: "ENTITY_FIELD",
                            key: "name"
                        }, {
                            type: "ENTITY_FIELD",
                            key: "parentId"
                        }
                    ]
                };

                return  widgetContext.http.post(`/api/entitiesQuery/find`, geofenceQueryParams);
            }),
            widgetContext.rxjs.switchMap((geofenceResponse) => {
                geofenceResponse.data.forEach(geofenceElement => {
                    const zoneId = geofenceElement.latest.ENTITY_FIELD.parentId.value;
                    const geofenceId = geofenceElement.entityId.id;
                    const geofenceName = geofenceElement.latest.ENTITY_FIELD.name.value;

                    const geofence = {
                        geofenceName
                    };

                    zones[zoneId].geofences.push(geofence);
                });

                Object.values(zones).forEach(zone => {
                    hierarchyTree[zone.locationId].zones.push(zone);
                });

                return widgetContext.rxjs.of(geofenceResponse);
            })
        )
        .subscribe(() => {
            if (params.filtersFormGroupValue) {
                const formValue = params.filtersFormGroupValue;
                vm.filtersFormGroup.patchValue(formValue);
                vm.allLocationsSelected = vm.locationOptions.length === formValue.location.length;
                vm.allZonesSelected = vm.zoneOptions.length === formValue.zone.length;
                vm.allTypesSelected = vm.typeOptions === formValue.type.length;
                vm.allDepartmentsSelected = vm.departmentOptions.length === formValue.department.length;
                vm.allAlertStatusesSelected = vm.alertStatusOptions.length === formValue.alertActivity.length;
            } else {
                vm.filtersFormGroup.get("location").setValue(vm.locationOptions.map(element => element.value));

                vm.filtersFormGroup.get("zone").setValue(vm.zoneOptions.map(zone => zone.value));
            }

        });

    vm.toggleAllSelection = function(controlName, options) {
        const controlValue = vm.filtersFormGroup.get(controlName).value;

        const allSelected = controlValue ? controlValue.length === options.length : false;

        vm.filtersFormGroup.get(controlName).setValue(allSelected ? []: options.map(option => option.value));

        switch (controlName) {
            case "type":
                vm.allTypesSelected = !allSelected;
                break;
            case "department":
                vm.allDepartmentsSelected = !allSelected;
                break;
            case "alertActivity": 
                vm.allAlertStatusesSelected = !allSelected;
                break;
            case "location":
                vm.allLocationsSelected = !allSelected;
                break;
            default: 
                vm.allZonesSelected = !allSelected;
                break;
        }

        widgetContext.detectChanges();
    };

    vm.onOptionSelected = function(controlName, options) {
        const selectedValues = vm.filtersFormGroup.get(controlName).value;

        const allOptionsSelected = selectedValues.length === options.length;

        switch (controlName) {
            case "type": 
                vm.allTypesSelected = allOptionsSelected;
                break;
            case "department":
                vm.allDepartmentsSelected = allOptionsSelected;
                break;
            case "alertActivity":
                vm.allAlertStatusesSelected = allOptionsSelected;
                break;
            case "location":
                vm.allLocationsSelected = allOptionsSelected;
                break;
            default: 
                vm.allZonesSelected = allOptionsSelected;
                break;
        }

    };

    vm.cancel = function() {
        vm.dialogRef.close(null);
    };

    function updateFilter(filterName, filterValue) {
        const filterId = Object.keys(aliasController.origFilters).find((filterId) => 
            aliasController.origFilters[filterId].filter === filterName
        );

        const filtersCopy = Object.assign({}, aliasController.origFilters);
        const condition = filtersCopy[filterId];
        if(condition && condition.keyFilters.length && condition.keyFilters[0].predicates.length){
            condition.keyFilters[0].predicates[0].keyFilterPredicate.value.defaultValue = filterValue.length ? filterValue.join(", ") : "{}";
            aliasController.updateUserFilter(condition);
            widgetContext.updateAliases();
        }
    }

    vm.applyFilters = function() {
        const formValue = vm.filtersFormGroup.value;

        params.filtersFormGroupValue = formValue;

        widgetContext.updateAliases();
        controller.updateState('default', params);

        const allAssets = [];
        const allGeofences = [];

        formValue.zone.forEach(zoneId => {
            const zone = zones[zoneId];
            zone.assets.forEach(asset => allAssets.push(asset));
            zone.geofences.forEach(geofence => allGeofences.push(geofence));
        });


        const filteredAssetNames = allAssets.filter(option => {
            const hasSuitableType = formValue.type && formValue.type.length
                ? formValue.type.includes(option.type)
                : true;

            const hasSuitableDepartment = true;

            const statuses = [];

            if (formValue.status.active) {
                statuses.push("true");
            }

            if (formValue.status.inactive) {
                statuses.push("false");
            }

            const hasSuitableStatus = statuses.length
                ? statuses.includes(option.status)
                : true;

            const hasSuitableAlertActivity = formValue.alertActivity && formValue.alertActivity.length
                ? formValue.alertActivity.includes(option.alertActivity)
                : true;

            return hasSuitableType && hasSuitableStatus && hasSuitableDepartment && hasSuitableAlertActivity;
        }).map(assetOption => assetOption.name);

        const filteredZoneNames = vm.zoneOptions.filter((option) => formValue.zone.includes(option.value)).map(zone => zone.label);

        const filteredGeofencesNames = allGeofences.map(geofence => geofence.geofenceName)

        if (aliasController.origFilters) {
            updateFilter("Monitoring zones", filteredZoneNames);
            updateFilter("Monitoring zones (Image on map)", filteredZoneNames);
            updateFilter("Monitoring zones (Not image on map)", filteredZoneNames);
            updateFilter("Monitoring assets", filteredAssetNames);
            updateFilter("Monitoring geofences", filteredGeofencesNames);
        }

        vm.dialogRef.close(null);
    };
}

