let $injector = widgetContext.$scope.$injector;
let dashboardService = $injector.get(widgetContext.servicesMap.get('dashboardService'));
let router = $injector.get(widgetContext.servicesMap.get('router'));

const pageLink = widgetContext.pageLink(100000);

const locationsDashboardName = "Locations dashboard";

let selectedLocation;

const locationQueryParams = {
    entityFilter: {
        type: "relationsQuery",
        rootEntity: entityId,
        direction: "FROM",
        maxLevel: 1,
        filters: [{
            relationType: "ZoneToLocation",
            entityTypes: ["ASSET"]
        }]
    },
    pageLink,
    entityFields: [
        {
            type: "ENTITY_FIELD",
            key: "name"
        },
        {
            type: "ENTITY_FIELD",
            key: "label"
        }
    ]
};

widgetContext.http.post(`/api/entitiesQuery/find`, locationQueryParams)
    .pipe(
        widgetContext.rxjs.switchMap((locationResponse) => {
            const location = locationResponse.data[0];
            selectedLocation = {
                entityId: location.entityId,
                entityName: location.latest.ENTITY_FIELD.name.value,
                entityLabel: location.latest.ENTITY_FIELD.label.value
            };

            return dashboardService.getTenantDashboards(pageLink);
        })
    )
    .subscribe(dashboardResponse => {
        const dashboardId = dashboardResponse.data.find(dashboard => dashboard.title === locationsDashboardName).id.id;

        const jsonStr = JSON.stringify([
            {
                id: "default",
                params: {
                    stateId: 'zoneDetails',
                    prevState: 'locationsDetails',
                    subState: 'general',
                    statesArray: [
                        {
                            stateId: 'locations', 
                            name: "Locations"
                        },
                    ],
                    selectedLocation,
                    selectedZone: {
                        entityName,
                        entityId,
                        entityLabel
                    }
                }
            }
        ]);

        const state = btoa(jsonStr);

        const queryParams = {
            stateId: "Locations",
            dashboardId,
            hideDashboardToolbar: true,
            state
        };

        router.navigate(['/iframeView'], {queryParams});
    });

